from pathlib import Path
import json,copy,re
R=Path(__file__).resolve().parent
if any(R.glob('image_manifest_artist*.json')):
    raise RuntimeError('이미지 제작 이후에는 이 이력용 초기 수정 스크립트를 재적용하지 않습니다. 최종 storyboards.json을 직접 수정하세요.')
d=json.loads((R/'director_draft.json').read_text(encoding='utf-8-sig'))
d['version']='v4.1_after_independent_cross_review'
C={c['id']:c for c in d['concepts']}
def s(cid,n):return C[cid]['shots'][n-1]
def u(cid,n,**kw):s(cid,n).update(kw)
u('C01',3,screen='직원이 새 회색 자료를 한꺼번에 넣자 결과 한 칸이 빈다. 질문에 계약선이 팽팽해지고 악마가 문 앞에서 검은 연기로 사라져 같은 화면의 방문 의자에 나타난다.',framing='고정된 깊은 초점 와이드. 왼쪽 전경 모니터·직원, 오른쪽 후경 열린 문·악마, 오른쪽 중경 빈 의자가 한 화면에 함께 보인다. 모니터의 빈 큰 칸은 후편집. 인서트·숨은 편집 없음.',first_frame='직원이 회색 자료 묶음을 모니터 옆에 들고 있다. 모니터는 입력 대기. 문 앞 악마와 빈 방문 의자가 모두 보임. 빨간 조건 카드는 아직 등장하지 않는다. 계약선은 느슨함.',next_motion='회색 자료 한꺼번에 입력→큰 결과 칸 하나 공백→질문→계약선 긴장→같은 고정 화면 안에서 악마가 문 앞에서 의자로 순간 이동. 효과는 후속 합성 연출이며 생성 성공을 보장하지 않음.',subtitle='후편집: 회색 자료 묶음·빈 큰 결과 칸. 빨간 조건 카드 없음.',continuity_in='K02의 결과 뒤 새 회색 자료 묶음을 적용. 첫 문제는 분량.',continuity_out='악마는 방문 의자에 착석, 회색 자료가 아직 한 묶음. 빨간 카드는 없음.')
